// Accept a raw webhook POST (data under .body) or a direct/sub-workflow call.
const raw = $input.first().json;
const src = raw.body || raw.lead || raw;

const clean = (v) => (v === undefined || v === null || v === false || v === '') ? null : String(v).trim();

const email = clean(src.email);
const phone = clean(src.phone) || clean(src.whatsapp);

if (!email && !phone) {
  throw new Error('Rejected: inbound lead has neither an email nor a phone number. Keys received: ' + Object.keys(src).join(', '));
}

return [{
  json: {
    lead: {
      name: clean(src.name) || clean(src.full_name) || 'Unknown',
      email: email,
      phone: phone,
      vehicle_interest: clean(src.vehicle_interest) || clean(src.vehicleInterest) || clean(src.message) || null,
      budget_aed: src.budget_aed ? Number(src.budget_aed) : null,
      source: clean(src.source) || 'webhook',
      received_at: new Date().toISOString()
    }
  }
}];

// The agent usually returns JSON, but often wrapped in ```json fences or with
// a sentence around it. The old version silently fell back to COLD/0 on any
// parse failure, which made every single lead look cold.
const lead = $('Validate & Enrich Input').first().json.lead;
const rawOut = $input.first().json;
const text = String(rawOut.output ?? rawOut.text ?? '').trim();

function extractJson(s) {
  if (!s) return null;
  // 1. straight parse
  try { return JSON.parse(s); } catch (e) {}
  // 2. strip markdown code fences
  const fenced = s.replace(/```(?:json)?/gi, '').trim();
  try { return JSON.parse(fenced); } catch (e) {}
  // 3. grab the outermost {...} block
  const first = fenced.indexOf('{');
  const last = fenced.lastIndexOf('}');
  if (first !== -1 && last > first) {
    try { return JSON.parse(fenced.slice(first, last + 1)); } catch (e) {}
  }
  return null;
}

let parsed = extractJson(text);
let parseFailed = false;

if (!parsed || typeof parsed !== 'object') {
  parseFailed = true;
  // Last resort: pull an intent word and a number out of the prose so a
  // genuinely hot lead is not silently downgraded to COLD.
  const intentMatch = text.match(/\b(HOT|WARM|COLD)\b/i);
  const scoreMatch = text.match(/\b(\d{1,3})\b/);
  parsed = {
    intent: intentMatch ? intentMatch[1].toUpperCase() : 'WARM',
    score: scoreMatch ? Math.min(100, parseInt(scoreMatch[1], 10)) : 50,
    reason: 'Agent did not return valid JSON. Raw output: ' + text.substring(0, 300)
  };
}

const intent = String(parsed.intent || '').toUpperCase();
const ai_decision = {
  intent: ['HOT', 'WARM', 'COLD'].includes(intent) ? intent : 'WARM',
  score: Number.isFinite(Number(parsed.score)) ? Number(parsed.score) : 50,
  reason: parsed.reason || null,
  parse_failed: parseFailed
};

return [{ json: { lead, ai_decision } }];

// n8n's Agent node accepts a maximum of 2 language models, so a deeper
// fallback chain has to be built as a retry ladder instead. Each tier swaps
// BOTH slots, giving 5 distinct models across 2 providers over 4 attempts.
// Model IDs were taken from OpenRouter's live /models list (tool-capable, free).
const TIERS = [
  { orModel: 'google/gemini-2.5-flash',                  groqModel: 'llama-3.3-70b-versatile' },
  { orModel: 'nvidia/nemotron-3-super-120b-a12b:free',   groqModel: 'llama-3.3-70b-versatile' },
  { orModel: 'google/gemma-4-31b-it:free',               groqModel: 'llama-3.3-70b-versatile' },
  { orModel: 'inclusionai/ling-3.0-flash:free',          groqModel: 'llama-3.3-70b-versatile' }
];

const prev = $input.first().json;
const attempt = Number(prev.attempt ?? -1) + 1;

if (attempt >= TIERS.length) {
  throw new Error('All ' + TIERS.length + ' model tiers failed for lead ' +
    ((prev.lead && prev.lead.email) || 'unknown') + '. Tried: ' +
    TIERS.map(t => t.orModel + ' / ' + t.groqModel).join(', '));
}

return [{ json: {
  lead: prev.lead,
  attempt: attempt,
  maxTiers: TIERS.length,
  orModel: TIERS[attempt].orModel,
  groqModel: TIERS[attempt].groqModel
} }];

